<script>
(()=>{const modal=document.getElementById('crmPeopleModal'),q=document.getElementById('crmPeopleSearch'),res=document.getElementById('crmPeopleResults'),btn=document.getElementById('crmPeopleSearchBtn');let rows=[],idx=-1,last='__dirty__';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function open(){modal.classList.add('open');modal.setAttribute('aria-hidden','false');q.value='';rows=[];idx=-1;last='__dirty__';res.innerHTML='<div class="crm-result crm-muted">Digite a pesquisa e pressione Enter.</div>';setTimeout(()=>q.focus(),25)}function close(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}function mark(){res.querySelectorAll('[data-i]').forEach((el,i)=>el.classList.toggle('sel',i===idx));res.querySelector('[data-i="'+idx+'"]')?.scrollIntoView({block:'nearest'})}function choose(i){const r=rows[i];if(!r)return;document.getElementById('crmPersonId').value=r.id||'';document.getElementById('crmCustomerName').value=r.name||'';document.getElementById('crmPhone').value=r.whatsapp||r.phone||'';document.getElementById('crmDocument').value=r.document||'';document.getElementById('crmEmail').value=r.email||'';document.getElementById('crmAddress').value=r.address_full||'';close();setTimeout(()=>document.getElementById('crmCustomerName').focus(),20)}function draw(data){rows=Array.isArray(data)?data:[];idx=rows.length?0:-1;res.innerHTML=rows.map((r,i)=>`<div class="crm-result ${i===0?'sel':''}" data-i="${i}"><strong>${esc(r.name||'')}</strong><small>${esc([(window.nexaMaskDoc||String)(r.document||''),r.whatsapp||r.phone,r.email,r.address_full].filter(Boolean).join(' · '))}</small></div>`).join('')||'<div class="crm-result crm-muted">Nenhum cliente encontrado.</div>';res.querySelectorAll('[data-i]').forEach(el=>el.addEventListener('click',()=>choose(Number(el.dataset.i))))}async function search(){btn.disabled=true;res.innerHTML='<div class="crm-result crm-muted">Pesquisando...</div>';try{const r=await fetch('crm_ajax.php?action=people&q='+encodeURIComponent(q.value.trim()),{headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Falha na pesquisa');draw(j.rows||[]);last=q.value}catch(e){rows=[];idx=-1;res.innerHTML='<div class="crm-result crm-muted">'+esc(e.message||'Falha na pesquisa')+'</div>'}finally{btn.disabled=false;q.focus()}}document.getElementById('crmPeopleOpen')?.addEventListener('click',open);document.getElementById('crmPeopleClose')?.addEventListener('click',close);btn?.addEventListener('click',search);document.getElementById('crmPeopleClear')?.addEventListener('click',()=>{document.getElementById('crmPersonId').value='';document.getElementById('crmCustomerName').focus()});q?.addEventListener('input',()=>{last='__dirty__';rows=[];idx=-1});q?.addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&rows.length){e.preventDefault();idx=Math.min(rows.length-1,idx+1);mark()}else if(e.key==='ArrowUp'&&rows.length){e.preventDefault();idx=Math.max(0,idx-1);mark()}else if(e.key==='Enter'){e.preventDefault();if(rows.length&&idx>=0&&last===q.value)choose(idx);else search()}});document.addEventListener('keydown',e=>{if(e.key==='F8'){e.preventDefault();open()}else if(e.key==='Escape'&&modal.classList.contains('open')){e.preventDefault();close()}});modal.addEventListener('mousedown',e=>{if(e.target===modal)close()});})();
</script>
